//! BIP-32 derivation as `ferrum-wallet` will use it, end to end.
//!
//! The official BIP-32 vector lives in the unit tests inside `src/bip32.rs`,
//! because it needs the private `master_from_seed_with_key` to substitute the
//! Bitcoin domain string. What is here instead is the Ferrum-side behaviour: a
//! mnemonic becomes a seed becomes a key tree becomes an address, and the same
//! phrase must produce the same wallet on every machine, forever.
//!
//! The golden values below are **generated by this implementation**, not
//! quoted from any specification. They exist to pin the derivation so that an
//! accidental change — a different domain string, a byte-order slip, an
//! x-only key where a compressed one belongs — fails loudly instead of
//! silently orphaning every existing wallet.

#![allow(clippy::unwrap_used)]

use std::collections::BTreeSet;

use ferrum_crypto::{
    Address, ChildNumber, CryptoError, DerivationPath, ExtendedKey, Mnemonic, TAG_SIGHASH,
    tagged_hash,
};
use ferrum_types::Network;

/// The all-zero 128-bit entropy phrase, the most widely reproduced BIP-39
/// mnemonic there is.
fn test_mnemonic() -> Mnemonic {
    Mnemonic::from_entropy(&[0u8; 16]).unwrap()
}

fn master() -> ExtendedKey {
    ExtendedKey::master_from_seed(&test_mnemonic().to_seed("")).unwrap()
}

#[test]
fn the_test_mnemonic_is_the_expected_one() {
    assert_eq!(
        test_mnemonic().phrase(),
        "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about"
    );
}

/// Golden fixture: pins the Ferrum key tree for a known phrase.
#[test]
fn a_known_phrase_derives_a_known_key_tree() {
    let m = master();
    assert_eq!(
        hex::encode(m.chain_code()),
        "3a6355c58b1e112dcc0fcaa7fa9e152a4a3062e923b8741f28f35e44bacb01de"
    );
    assert_eq!(
        hex::encode(m.secret_key().to_bytes()),
        "5ed02caee4b326f8264cc1f3666c09e2fb2ab4a13dcd0ae8443189999cbc86ae"
    );

    let key = m.derive_path(&DerivationPath::ferrum(0, 0, 0).unwrap()).unwrap();
    assert_eq!(
        hex::encode(key.public_key().as_bytes()),
        "d63d39e02437c9d5689d2078f1f009b82939cc60bfa7f5d5a4d2f303343690fb"
    );
    assert_eq!(
        Address::p2pkh(Network::Mainnet, &key.public_key()).encode(),
        "fer1qpwveru08qwla47tf5656l8jegnm4t2yvujm9v7w"
    );
}

#[test]
fn the_same_seed_gives_the_same_tree_every_time() {
    let path = DerivationPath::ferrum(0, 0, 0).unwrap();
    let a = master().derive_path(&path).unwrap();
    let b = master().derive_path(&path).unwrap();
    assert_eq!(a, b);
    assert_eq!(a.secret_key(), b.secret_key());
    assert_eq!(a.public_key(), b.public_key());
    assert_eq!(a.chain_code(), b.chain_code());
}

#[test]
fn a_different_passphrase_gives_a_different_wallet() {
    let phrase = test_mnemonic();
    let plain = ExtendedKey::master_from_seed(&phrase.to_seed("")).unwrap();
    let hidden = ExtendedKey::master_from_seed(&phrase.to_seed("25th word")).unwrap();
    assert_ne!(plain, hidden);
    assert_ne!(plain.public_key(), hidden.public_key());
}

#[test]
fn hardened_and_normal_paths_diverge() {
    let m = master();
    let normal = m.derive_path(&"m/0".parse::<DerivationPath>().unwrap()).unwrap();
    let hardened = m.derive_path(&"m/0'".parse::<DerivationPath>().unwrap()).unwrap();
    assert_ne!(normal, hardened);
    assert_ne!(normal.public_key(), hardened.public_key());
    assert!(!normal.child_number().is_hardened());
    assert!(hardened.child_number().is_hardened());
    assert_eq!(normal.parent_fingerprint(), hardened.parent_fingerprint());
}

#[test]
fn twenty_consecutive_addresses_are_all_distinct() {
    let m = master();
    let mut addresses = BTreeSet::new();
    let mut keys = BTreeSet::new();
    for i in 0..20u32 {
        let key = m.derive_path(&DerivationPath::ferrum(0, 0, i).unwrap()).unwrap();
        assert!(keys.insert(key.public_key().to_bytes()), "index {i} repeated a key");
        let address = Address::p2pkh(Network::Mainnet, &key.public_key()).encode();
        assert!(addresses.insert(address), "index {i} repeated an address");
    }
}

#[test]
fn receive_and_change_branches_do_not_overlap() {
    let m = master();
    let mut seen = BTreeSet::new();
    for change in 0..2u32 {
        for i in 0..10u32 {
            let key = m.derive_path(&DerivationPath::ferrum(0, change, i).unwrap()).unwrap();
            assert!(seen.insert(key.public_key().to_bytes()), "change {change} index {i} collided");
        }
    }
}

#[test]
fn accounts_are_isolated() {
    let m = master();
    let a = m.derive_path(&DerivationPath::ferrum(0, 0, 0).unwrap()).unwrap();
    let b = m.derive_path(&DerivationPath::ferrum(1, 0, 0).unwrap()).unwrap();
    assert_ne!(a.public_key(), b.public_key());
    assert_ne!(a.chain_code(), b.chain_code());
}

#[test]
fn a_derived_key_signs_and_verifies_through_its_address() {
    let key = master().derive_path(&DerivationPath::ferrum(0, 0, 3).unwrap()).unwrap();
    let pk = key.public_key();
    let address = Address::p2pkh(Network::Mainnet, &pk);

    // The address commits to this key and to no other.
    assert_eq!(Address::decode(&address.encode()).unwrap(), address);
    let other = master().derive_path(&DerivationPath::ferrum(0, 0, 4).unwrap()).unwrap();
    assert_ne!(Address::p2pkh(Network::Mainnet, &other.public_key()), address);

    let sighash = tagged_hash(TAG_SIGHASH, b"a preimage from ferrum-script");
    let sig = key.secret_key().sign_deterministic(&sighash);
    assert!(pk.verify(&sighash, &sig).is_ok());
    assert!(other.public_key().verify(&sighash, &sig).is_err());
}

#[test]
fn a_seed_from_a_restored_phrase_matches_the_original() {
    let original = test_mnemonic();
    let restored = Mnemonic::from_phrase(original.phrase()).unwrap();
    assert_eq!(original, restored);
    assert_eq!(original.to_seed("pass"), restored.to_seed("pass"));

    let path = DerivationPath::ferrum(0, 0, 0).unwrap();
    let a = ExtendedKey::master_from_seed(&original.to_seed("pass")).unwrap();
    let b = ExtendedKey::master_from_seed(&restored.to_seed("pass")).unwrap();
    assert_eq!(a.derive_path(&path).unwrap(), b.derive_path(&path).unwrap());
}

#[test]
fn deep_derivation_stops_at_depth_255() {
    // 255 real derivations is slow but not prohibitive, and it is the only way
    // to reach the boundary honestly from the public API.
    let mut key = master();
    for _ in 0..255u16 {
        key = key.derive_child(ChildNumber::ZERO).unwrap();
    }
    assert_eq!(key.depth(), 255);
    assert_eq!(key.derive_child(ChildNumber::ZERO), Err(CryptoError::DepthOverflow));
}

#[test]
fn every_seed_length_in_range_is_accepted() {
    for len in [16usize, 24, 32, 48, 64] {
        let seed = vec![0x5au8; len];
        assert!(ExtendedKey::master_from_seed(&seed).is_ok(), "{len}-byte seed rejected");
    }
    assert_eq!(ExtendedKey::master_from_seed(&[0x5a; 15]), Err(CryptoError::InvalidSeedLength(15)));
    assert_eq!(ExtendedKey::master_from_seed(&[0x5a; 65]), Err(CryptoError::InvalidSeedLength(65)));
}

#[test]
fn path_text_survives_a_round_trip_through_derivation() {
    for text in ["m", "m/0", "m/0'", "m/44'/7767'/0'/0/0", "m/44'/7767'/12'/1/999"] {
        let path: DerivationPath = text.parse().unwrap();
        assert_eq!(path.to_string(), text);
        let key = master().derive_path(&path).unwrap();
        assert_eq!(usize::from(key.depth()), path.len());
    }
}
